#include "dashboard.hpp"
#include <fstream>
#include <sstream>
namespace exotic::runtime {namespace {std::string esc(std::string_view s){std::string r;for(char c:s){if(c=='"'||c=='\\')r.push_back('\\');if(c=='\n'){r+="\\n";continue;}r.push_back(c);}return r;}}
DashboardWriter::DashboardWriter(std::filesystem::path d):directory_(std::move(d)){std::filesystem::create_directories(directory_);}std::filesystem::path DashboardWriter::json_path()const{return directory_/"runtime-status.json";}std::filesystem::path DashboardWriter::text_path()const{return directory_/"runtime-status.txt";}
void DashboardWriter::write(const RuntimeSnapshot&s){auto tmp=json_path();tmp+=".tmp";std::ofstream j(tmp,std::ios::trunc);j<<"{\n  \"workspace\": \""<<esc(s.workspace_id)<<"\",\n  \"mode\": \""<<to_string(s.mode)<<"\",\n  \"running\": "<<(s.running?"true":"false")<<",\n  \"emergency_stop\": "<<(s.emergency_stop?"true":"false")<<",\n  \"services\": [\n";for(std::size_t i=0;i<s.services.size();++i){auto&h=s.services[i];j<<"    {\"name\":\""<<esc(h.service)<<"\",\"state\":\""<<to_string(h.state)<<"\",\"health\":\""<<to_string(h.level)<<"\",\"message\":\""<<esc(h.message)<<"\"}"<<(i+1<s.services.size()?",":"")<<"\n";}j<<"  ],\n  \"active_alerts\": "<<s.alerts.size()<<"\n}\n";j.close();std::error_code ec;std::filesystem::remove(json_path(),ec);std::filesystem::rename(tmp,json_path());std::ofstream t(text_path(),std::ios::trunc);t<<"EXOTIC CONTINUOUS OPERATIONS 1.0\nworkspace="<<s.workspace_id<<"\nmode="<<to_string(s.mode)<<"\nrunning="<<(s.running?"true":"false")<<"\nemergency_stop="<<(s.emergency_stop?"active":"clear")<<"\n\nSERVICES\n";for(auto&h:s.services)t<<h.service<<"  "<<to_string(h.state)<<"  "<<to_string(h.level)<<"  "<<h.message<<"\n";t<<"\nactive_alerts="<<s.alerts.size()<<"\n";}
}
